window.VF2_UNITS = {"5":{"unit":5,"code":"VF2-U05","title":"PEOPLE & THE SOCIETY","startNumber":73,"endNumber":88,"entries":[{"number":73,"term":"ordinary (a) ~ normal (a) ~ common (a) # popular (a)","spoken":"ordinary , normal , common , popular","ipa":"ordinary /ˈɔːrdəˌnɛri/ · normal /ˈnɔːrməl/ · common /ˈkɑːmən/ · popular /ˈpɑːpjəlɚ/","type":"adjective · word family","meaning":"bình thường, thông thường ~ phổ biến, thường gặp # được nhiều người yêu thích","definition":"Ordinary or normal means not unusual; common means frequent; popular means liked by many people.","note":"ordinary/normal là bình thường; common là thường gặp/phổ biến; popular là được nhiều người ưa thích.","example":"The documentary follows the ordinary routines of people whose experiences are rarely shown in the media."},{"number":74,"term":"infamous (a) ~ notorious (a) ~ famous (a)","spoken":"infamous , notorious , famous","ipa":"infamous /ˈɪnfəməs/ · notorious /noʊˈtɔːriəs/ · famous /ˈfeɪməs/","type":"adjective · word family","meaning":"tai tiếng, khét tiếng vì điều xấu ~ nổi tiếng","definition":"Infamous and notorious mean well known for something bad; famous is neutral or positive unless the context says otherwise.","note":"infamous/notorious đều là nổi tiếng vì điều xấu; không dùng thay cho famous khi sắc thái tích cực/trung tính.","example":"The famous actor played an infamous leader who was notorious for cruelty."},{"number":75,"term":"(dis)approve of ~ (dis)agree with · (dis)approval (n) of st","spoken":"(dis)approve of , (dis)agree with , (dis)approval of something","ipa":"approve /əˈpruːv/ · agree /əˈɡriː/ · approval /əˈpruːvəl/","type":"noun · phrase / pattern · word family","meaning":"tán thành hoặc không tán thành điều gì ~ đồng ý hoặc không đồng ý với ai hay ý kiến · sự tán thành hoặc không tán thành","definition":"To have a positive or negative opinion of something; approval and disapproval are the related nouns.","note":"approve of là tán thành/cho là tốt; agree with là đồng ý với ý kiến/người. Hai cụm gần nghĩa nhưng không hoàn toàn thay thế.","example":"Many residents approved of the plan, but others disagreed with its environmental impact."},{"number":76,"term":"do sb a favour ~ help sb · owe sb a favour","spoken":"do somebody a favour , help somebody , owe somebody a favour","ipa":"favour /ˈfeɪvɚ/ · help /hɛlp/ · owe /oʊ/","type":"phrase / pattern · word family","meaning":"giúp ai một việc · nợ ai một ân tình hoặc sự giúp đỡ","definition":"To help somebody, creating a favour that may later be returned.","note":"do sb a favour là giúp ai; owe sb a favour là mang ơn và nên giúp lại.","example":"A colleague did me a favour by covering my shift, so I still owe her a favour."},{"number":77,"term":"object to st ~ oppose st","spoken":"object to something , oppose something","ipa":"object /əbˈdʒekt/ · oppose /əˈpoʊz/","type":"phrase / pattern · word family","meaning":"phản đối","definition":"To express disagreement with or resistance to a proposal, idea, or action.","note":"object to + noun/V-ing; oppose + noun trực tiếp, không có to.","example":"Local groups objected to the proposal and formally opposed the destruction of the park."},{"number":78,"term":"ask after sb","spoken":"ask after somebody","ipa":"ask /æsk/ · after /ˈæftɚ/","type":"phrasal verb","meaning":"hỏi thăm sức khỏe hoặc tình hình của ai","definition":"To ask about somebody's health or situation.","note":"Giữ đúng mẫu từ đi kèm: ask after sb.","example":"She called the hospital to ask after her neighbour following the operation."},{"number":79,"term":"fall for (a trick/a lie)","spoken":"fall for (a trick or a lie)","ipa":"fall /fɔːl/","type":"phrasal verb","meaning":"bị lừa","definition":"To be tricked into believing a lie or dishonest story.","note":"","example":"Several users fell for the false advertisement because it copied a trusted brand."},{"number":80,"term":"look up to sb >< look down on sb","spoken":"look up to somebody , look down on somebody","ipa":"look /lʊk/ · up /ʌp/ · down /daʊn/","type":"phrasal verb · word family","meaning":"kính trọng, ngưỡng mộ ai · coi thường, khinh thường ai","definition":"To respect and admire somebody versus to consider somebody inferior.","note":"look up to là kính trọng; look down on là coi thường.","example":"Young athletes often look up to successful players, but they should never look down on beginners."},{"number":81,"term":"pass away ~ die","spoken":"pass away , die","ipa":"pass /pæs/ · away /əˈweɪ/ · die /daɪ/","type":"phrasal verb · word family","meaning":"qua đời, chết","definition":"A polite expression meaning to die.","note":"","example":"The writer passed away at the age of ninety, surrounded by members of her family."},{"number":82,"term":"settle down","spoken":"settle down","ipa":"settle /ˈsɛtəl/ · down /daʊn/","type":"phrasal verb","meaning":"an cư lạc nghiệp","definition":"To begin a stable, quiet life, often with a permanent home or family.","note":"","example":"After years of travel, they settled down in a small town and started a family."},{"number":83,"term":"pick on sb","spoken":"pick on somebody","ipa":"pick /pɪk/","type":"phrasal verb","meaning":"bắt nạt, gây khó dễ hoặc thường xuyên chỉ trích ai","definition":"To repeatedly treat one person unfairly, criticize them, or bully them.","note":"Giữ đúng mẫu từ đi kèm: pick on sb.","example":"Older students were warned not to pick on younger pupils during group activities."},{"number":84,"term":"put sb down","spoken":"put somebody down","ipa":"put /pʊt/ · down /daʊn/","type":"phrasal verb","meaning":"hạ bệ, chỉ trích ai","definition":"To criticize, humiliate, or make somebody feel less confident.","note":"Giữ đúng mẫu từ đi kèm: put sb down.","example":"A good leader gives constructive feedback instead of putting team members down."},{"number":85,"term":"take sb aback ~ surprise sb # take sb back","spoken":"take somebody aback , surprise somebody , take somebody back","ipa":"take /teɪk/ · aback /əˈbæk/ · surprise /sɚˈpraɪz/ · back /bæk/","type":"phrasal verb · word family","meaning":"làm ai bất ngờ hoặc sửng sốt · đưa ai trở lại; gợi ai nhớ về quá khứ","definition":"Take somebody aback means surprise or shock them; take somebody back means return them somewhere or remind them of the past.","note":"Cụm đúng là take sb aback; take sb back lại thường là đưa ai trở lại hoặc gợi nhớ quá khứ.","example":"The news took her aback, while the old photograph took her back to her childhood."},{"number":86,"term":"stand up for sb","spoken":"stand up for somebody","ipa":"stand /stænd/ · up /ʌp/","type":"phrasal verb","meaning":"đứng về phe ai…","definition":"To defend or support somebody who is being criticized or treated unfairly.","note":"Giữ đúng mẫu từ đi kèm: stand up for sb.","example":"Several witnesses stood up for the student after she was unfairly blamed."},{"number":87,"term":"fall out with sb","spoken":"fall out with somebody","ipa":"fall /fɔːl/ · out /aʊt/","type":"phrasal verb","meaning":"cãi nhau với ai","definition":"To have an argument and stop being friendly with somebody.","note":"Giữ đúng mẫu từ đi kèm: fall out with sb.","example":"The two colleagues fell out over the report but continued to work professionally."},{"number":88,"term":"make up","spoken":"make up","ipa":"make /meɪk/ · up /ʌp/","type":"phrasal verb","meaning":"làm lành, làm hòa","definition":"To become friendly again after an argument.","note":"make up có nhiều nghĩa; trong ngữ cảnh quan hệ, make up = làm hòa.","example":"They discussed the misunderstanding honestly and made up before the project ended."}],"pronunciationFocus":[{"entryNumber":74,"points":[{"category":"word-stress","note":"infamous /ˈɪnfəməs/ nhấn âm 1; notorious /noʊˈtɔːriəs/ nhấn âm 2"}]},{"entryNumber":77,"points":[{"category":"final-sound","note":"object /əbˈdʒekt/: giữ đủ cụm âm cuối /kt/"}]},{"entryNumber":78,"points":[{"category":"linking","note":"ask‿after: nối /k/ sang /æ/"}]}]}};
